var a=`1066-black-pepper-crab`;var n=`world-1066`;var t=`SG`;var r=`southeast-asia`;var s=4;var o=34;var l={en:`Black Pepper Crab`,ua:`Краб із чорним перцем`};var g={en:`Black Pepper Crab is a dish from Singapore prepared with blue crab, garlic, light soy sauce, oyster sauce. This is a home-scale version with measured ingredients in the individual steps where they are used. Blue crab replaces mud crab.`,ua:`Краб із чорним перцем, страва кухні країни Сінгапур, яку готують із таких продуктів: блакитний краб, часник, світлий соєвий соус, устричний соус. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Синій краб замінює мангрового.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 10 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 10 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:10,i:[[`blue-crab`,1150,`g`],[`canola-oil`,50,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`garlic`,5,`clove`],[`ground-ginger`,35,`g`],[`ground-black-pepper`,12,`g`],[`unsalted-butter`,65,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 13 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 13 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:13,i:[[`light-soy-sauce`,38,`ml`],[`oyster-sauce`,50,`ml`],[`water`,200,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,45,`g`]]}];var d={slug:a,id:n,country:`SG`,region:r,servings:4,minutes:34,title:l,text:g,steps:u};export{t as country,d as default,n as id,o as minutes,r as region,s as servings,a as slug,u as steps,g as text,l as title};